4void display_misses(int misses) {
5
6    // add the body parts of the Hangman
7    // according to the number of misses
8    switch (misses) {
9
10        // display an empty gallows when misses = 0
11        case 0:
12            cout << "  +---+ " << endl;
13            cout << "  |   | " << endl;
14            cout << "      | " << endl;
15            cout << "      | " << endl;
16            cout << "      | " << endl;
17            cout << "      | " << endl;
18            cout << "=========" << endl;
19            break;
20
21        // draw the Hangman's head
22        case 1:
23            cout << "  +---+ " << endl;
24            cout << "  |   | " << endl;
25            cout << "  O   | " << endl;
26            cout << "      | " << endl;
27            cout << "      | " << endl;
28            cout << "      | " << endl;
29            cout << "=========" << endl;
30            break;
31
32        // draw the Hangman's torso
33        case 2:
34            cout << "  +---+ " << endl;
35            cout << "  |   | " << endl;
36            cout << "  O   | " << endl;
37            cout << "  |   | " << endl;
38            cout << "      | " << endl;
39            cout << "      | " << endl;
40            cout << "=========" << endl;
41            break;
42
43        // draw the Hangman's right arm
44        case 3:
45            cout << "  +---+ " << endl;
46            cout << "  |   | " << endl;
47            cout << "  O   | " << endl;
48            cout << " /|   | " << endl;
49            cout << "      | " << endl;
50            cout << "      | " << endl;
51            cout << "=========" << endl;
52            break;
53
54        // draw the Hangman's left arm
55        case 4:
56            cout << "  +---+ " << endl;
57            cout << "  |   | " << endl;
58            cout << "  O   | " << endl;
59            cout << " /|\\  | " << endl;
60            cout << "      | " << endl;
61            cout << "      | " << endl;
62            cout << "=========" << endl;
63            break;
64
65        // draw the Hangman's left leg
66        case 5:
67            cout << "  +---+ " << endl;
68            cout << "  |   | " << endl;
69            cout << "  O   | " << endl;
70            cout << " /|\\  | " << endl;
71            cout << " /    | " << endl;
72            cout << "      | " << endl;
73            cout << "=========" << endl;
74            break;
75
76        // draw the Hangman's right leg
77        case 6:
78            cout << "  +---+ " << endl;
79            cout << "  |   | " << endl;
80            cout << "  O   | " << endl;
81            cout << " /|\\  | " << endl;
82            cout << " / \\  | " << endl;
83            cout << "      | " << endl;
84            cout << "=========" << endl;
85            break;
86    }
87}
